<template><q-page class="page"><section class="top"><p class="eyebrow">ADMINISTRAÇÃO</p><h1>Importar questões</h1><p>Envie PDFs para o banco global; a análise ocorre antes da persistência.</p></section><q-banner v-if="error" rounded class="error">{{ error }}</q-banner><q-banner v-if="success" rounded class="success">{{ success }}</q-banner><q-card flat class="card"><q-card-section><h2>Importar PDFs de questões</h2><q-file v-model="pdfDocuments" outlined multiple accept="application/pdf,.pdf" label="PDFs com questões" use-chips clearable/><div class="action"><span>{{ pdfDocuments.length ? pdfDocuments.length + ' arquivo(s) selecionado(s)' : 'Selecione um ou mais PDFs.' }}</span><q-btn unelevated no-caps color="primary" label="Enviar para a fila" :disable="!pdfDocuments.length" :loading="loading" @click="queuePdfBatch"/></div></q-card-section></q-card><q-card v-if="activePdfJobs.length" flat class="card"><q-card-section><div class="head"><h2>Importações em andamento</h2><q-btn flat dense no-caps icon="refresh" label="Atualizar" @click="refreshPdfJobs"/></div><import-job-list :jobs="activePdfJobs" cancellable @cancel="cancelPdfJob" @inspect="loadPdfAnalyses"/></q-card-section></q-card><q-card v-if="pdfJobTotal || historyLoading" flat class="card"><q-card-section><h2>Histórico de importações</h2><q-inner-loading :showing="historyLoading"/><q-banner v-if="!historyLoading && !finishedPdfJobs.length" rounded class="empty">Nenhuma importação concluída ou com falha foi encontrada.</q-banner><import-job-list v-else :jobs="finishedPdfJobs" @inspect="loadPdfAnalyses"/></q-card-section></q-card><q-card v-if="analysisJobId" flat class="card review"><q-card-section><div class="head"><div><h2>Revisão da análise</h2><p>Achados sem revelar o gabarito inferido.</p></div><q-btn flat dense no-caps icon="close" label="Fechar" @click="clearPdfAnalyses"/></div><q-inner-loading :showing="analysisLoading"/><q-banner v-if="!analysisLoading && !analyses.length" rounded class="empty">Ainda não há análise concluída para esta importação.</q-banner><q-list v-else separator><q-item v-for="analysis in analyses" :key="analysis.id"><q-item-section><q-item-label><q-badge outline color="warning">{{ analysis.answerKeyAssessment }}</q-badge><q-badge class="q-ml-sm" outline color="primary">{{ analysis.imageAssessment }}</q-badge><span class="q-ml-sm">{{ analysis.board || 'Banca não confirmada' }} · {{ analysis.year || 'ano não confirmado' }}</span></q-item-label><q-item-label v-for="finding in analysis.findings" :key="finding.code + finding.safeSummary" caption class="finding"><q-icon name="warning_amber" color="warning"/> {{ finding.safeSummary }} <span v-if="finding.evidencePages.length">(p. {{ finding.evidencePages.join(', ') }})</span></q-item-label><q-item-label v-if="analysis.imageAssessment !== 'CONSISTENT'" class="visual-warning"><q-icon name="image_search"/> Discrepância visual: confira as páginas {{ analysis.imageAnchors.map(anchor => anchor.sourcePage).join(', ') || analysis.evidencePages.join(', ') }}.</q-item-label></q-item-section></q-item></q-list></q-card-section></q-card></q-page></template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import ImportJobList from './ImportJobList.vue'
import { useImport } from './useImport'
const pdfDocuments = ref<File[]>([]); const format = ref<'JSON' | 'CSV'>('JSON'); const content = ref(''); const syllabusId = ref('')
const { activePdfJobs, analyses, analysisJobId, analysisLoading, cancelPdfJob, clearPdfAnalyses, commit, error, finishedPdfJobs, historyLoading, loadPdfAnalyses, loadPdfJobs, loading, pdfJobTotal, preview, queuePdfs, refreshPdfJobs, report, success } = useImport()
async function queuePdfBatch(): Promise<void> { await queuePdfs(pdfDocuments.value); pdfDocuments.value = [] }
async function previewImport(): Promise<void> { await preview(format.value, content.value) } async function commitImport(): Promise<void> { await commit(syllabusId.value) }
onMounted(() => { void loadPdfJobs() })
</script>
<style scoped>.page{max-width:1100px;margin:auto;padding:42px 34px}.top{margin-bottom:20px}.eyebrow{color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.card{background:#fff;border:1px solid #e5ecf6;border-radius:20px;margin-top:16px}.head,.action{display:flex;justify-content:space-between;gap:16px;align-items:center}.error{margin-top:16px;background:#fff3f2;color:#ae2f25}.success{margin-top:16px;background:#edf9f1;color:#22764a}.empty{background:#f5f8fd;color:#637797}.review{border-left:4px solid #f2a900}.finding{margin-top:6px;color:#735100}.visual-warning{margin-top:8px;color:#9a4e00;font-weight:700}@media(max-width:700px){.page{padding:28px 16px}.head,.action{align-items:stretch;flex-direction:column}}</style>
